/* Baseball: 101 questions, 4 rabbit holes. Generated by question-sources/build_questions.js */
(window.TRIVIA_TOPICS = window.TRIVIA_TOPICS || {})["baseball"] = {
  questions: [
    {"id":"baseball-001","q":"How many strikes does it take to strike out?","c":["3","2","4","5"],"skill":"rules","why":"\"Strike one, strike two, strike three — you're OUT!\"","hint":"The umpire counts \"strike one, strike two, strike...\" what's next?","deeper":[{"t":"mc","k":"more","q":"How many 'balls' (bad pitches) does a batter need to get a walk to first base?","c":["4","3","2","6"],"why":"Four balls = a walk. The batter gets to go to first base for free."},{"t":"talk","k":"why","q":"Why might a smart batter NOT swing at a pitch way outside?","peek":"Hard to hit well; if they don't swing it's a 'ball', getting closer to a walk.","clue":"If you don't swing and the pitch is outside, is it a ball or a strike?"}]},
    {"id":"baseball-002","q":"How many players does the fielding team have on the field?","c":["9","6","11","5"],"skill":"rules","why":"9 players: pitcher, catcher, 4 infielders and 3 outfielders.","hint":"Pitcher + catcher = 2. Four in the infield, three in the outfield. Add them up!","deeper":[{"t":"mc","k":"more","q":"Which player stands on the mound in the middle of the infield?","c":["The pitcher","The catcher","The shortstop","The umpire"],"why":"The pitcher throws from the mound — a little hill in the middle of the diamond."},{"t":"talk","k":"more","q":"The catcher wears a mask, chest protector and shin guards. Why does the catcher need more gear than other players?","peek":"Fast pitches and foul tips come right at them all game long.","clue":"Who is closest to the batter and catching every single pitch?"}]},
    {"id":"baseball-003","q":"Which Major League Baseball team plays in Canada?","c":["Toronto Blue Jays","New York Yankees","Boston Red Sox","Chicago Cubs"],"skill":"teams","why":"The Toronto Blue Jays — Canada's MLB team!","hint":"It's named after a blue bird...","deeper":[{"t":"mc","k":"more","q":"The Blue Jays won back-to-back World Series championships in...","c":["1992 and 1993","2000 and 2001","1950 and 1951","They never won"],"why":"1992 and 1993! Joe Carter's walk-off home run won it in 1993."},{"t":"mc","k":"more","q":"What is the Blue Jays' home stadium called?","c":["Rogers Centre","Fenway Park","Wrigley Field","Scotiabank Arena"],"why":"Rogers Centre in Toronto — its roof can open and close!"},{"t":"talk","k":"whatif","q":"The Rogers Centre has a roof that opens and closes. Why would that be handy for baseball in Toronto?","peek":"Rain/cold/snow in spring and fall — close it; open it on sunny days.","clue":"What's Toronto weather like in April?"}]},
    {"id":"baseball-004","q":"What do you call hitting the ball over the outfield fence?","c":["A home run","A strikeout","A bunt","A foul ball"],"skill":"rules","why":"A home run! The batter gets to jog around all the bases.","hint":"The batter gets to run all the way around back to ___ plate.","deeper":[{"t":"mc","k":"more","q":"A home run when all three bases have runners on them is called a...","c":["Grand slam","Triple play","Hat trick","Touchdown"],"why":"A grand slam! The biggest hit in baseball."},{"t":"mc","k":"more","q":"How many runs score on a grand slam?","c":["4","3","1","5"],"why":"3 runners on base + the batter = 4 runs!","hint":"There are 3 runners on base. Then the batter scores too. 3 + 1 = ?"}]},
    {"id":"baseball-005","q":"How many innings are in a regular Major League game?","c":["9","7","5","12"],"skill":"rules","why":"9 innings! If it's tied, they play extra innings.","hint":"It's one less than 10.","deeper":[{"t":"mc","k":"more","q":"Each team gets 3 outs in an inning. In 9 innings, how many outs does a team get when batting?","c":["27","12","9","30"],"why":"3 × 9 = 27 outs!","hint":"3 outs, 9 times. Try counting by 3s: 3, 6, 9, 12..."},{"t":"mc","k":"more","q":"What happens if the game is tied after 9 innings?","c":["Extra innings","It's a tie, go home","Penalty shots","Coin flip"],"why":"They keep playing extra innings until someone is ahead after a full inning."}]},
    {"id":"baseball-006","q":"How many bases are there, counting home plate?","c":["4","3","5","9"],"skill":"rules","why":"First, second, third... and home! That's 4.","hint":"First, second, third — plus home. Count them!","deeper":[{"t":"mc","k":"more","q":"The infield is shaped like a...","c":["Diamond (a square turned on its corner)","Circle","Triangle","Star"],"why":"It's called the diamond! It's really a square tipped on its corner."},{"t":"talk","k":"more","q":"After hitting the ball, why do batters run THROUGH first base instead of stopping on it?","peek":"Stopping slows you down; you're allowed to overrun first base, so running through is fastest.","clue":"Is it faster to stop on a spot or run right past it?"}]},
    {"id":"baseball-007","q":"Which baseball hero broke the colour barrier in 1947 — after playing a season in Montreal?","c":["Jackie Robinson","Babe Ruth","Derek Jeter","Joe Carter"],"skill":"teams","why":"Jackie Robinson! He played for the Montreal Royals in 1946, then became the first Black player in modern Major League Baseball.","hint":"His number was 42, and every MLB team has retired it.","deeper":[{"t":"mc","k":"more","q":"On Jackie Robinson Day (April 15), what do ALL MLB players do?","c":["Wear number 42","Play barefoot","Bat left-handed","Skip the game"],"why":"Everyone wears 42 to honour him!"},{"t":"talk","k":"why","q":"Why was it so brave for Jackie Robinson to be the first Black player in the major leagues?","peek":"Faced unfair treatment/racism and mean crowds but stayed calm, played great, opened the door for others.","clue":"How do you think some people treated him back then? How did he respond?"}]},
    {"id":"baseball-008","q":"In the middle of the 7th inning, what do fans do?","c":["Stand up, stretch and sing","Go home","Run onto the field","Take a nap"],"skill":"teams","why":"The seventh-inning stretch! Fans sing \"Take Me Out to the Ball Game.\"","hint":"It's called the seventh-inning ___. Sounds like what you do when you wake up!","deeper":[{"t":"mc","k":"more","q":"In \"Take Me Out to the Ball Game,\" the fan asks for peanuts and...","c":["Cracker Jack","Pizza","Hot chocolate","Popcorn"],"why":"\"Buy me some peanuts and Cracker Jack!\""},{"t":"talk","k":"why","q":"Why might it be a good idea to stand up and stretch halfway through a long game — or a long car ride?","peek":"Sitting a long time makes you stiff/sleepy; moving gets blood flowing.","clue":"How do your legs feel after sitting for a really long time?"}]},
    {"id":"baseball-009","q":"A batter gets 3 hits in 10 tries. What is their batting average?","c":[".300",".030","3.10",".100"],"skill":"math","why":"3 out of 10 = 0.300 (we say 'three hundred'). That's really good in the big leagues!","hint":"3 out of 10 is like 30 out of 100. Which answer has a 3 right after the dot?","deeper":[{"t":"mc","k":"whatif","q":"What would 2 hits in 4 tries be?","c":[".500",".200",".240",".024"],"why":"2 out of 4 is half, and half is .500!","hint":"Is 2 out of 4 more or less than half?"},{"t":"talk","k":"more","q":"A .300 hitter is a star — but that means they DON'T get a hit 7 times out of 10! What does that teach us about trying hard things?","peek":"Even the best fail a lot; keep trying, mistakes are normal.","clue":"If even the best players miss most of the time, should you give up after a miss?"}]},
    {"id":"baseball-010","q":"What is a 'double play'?","c":["Getting 2 outs on one play","Playing two games in one day","Hitting the ball twice","Two pitchers at once"],"skill":"rules","why":"Two outs on one play — like a ground ball, throw to second, then to first!","hint":"'Double' means two. Two of what does the fielding team want?","deeper":[{"t":"mc","k":"whatif","q":"So what would a TRIPLE play be?","c":["3 outs on one play","3 home runs","3 strikes","3 games"],"why":"Three outs on one play — the whole inning ends in one moment!"},{"t":"talk","k":"more","q":"Triple plays are super rare. Why? What has to happen for one to be possible?","peek":"Need at least 2 runners on base and no outs, plus a perfect hit and super-fast fielding.","clue":"How many runners need to be on base to get 3 outs at once?"}]},
    {"id":"baseball-011","q":"How far apart are the bases on a Major League field?","c":["90 feet (about 27 metres)","9 feet","900 feet","30 feet"],"skill":"rules","why":"90 feet — about 27 metres between each base.","hint":"It's more than 50 feet but less than 100 feet.","deeper":[{"t":"mc","k":"more","q":"A home run trip goes around all 4 bases (90 feet each). How far is that?","c":["360 feet","90 feet","180 feet","400 feet"],"why":"90 + 90 + 90 + 90 = 360 feet!","hint":"Add 90 four times — or think 4 × 9 = 36, then add a zero."},{"t":"talk","k":"more","q":"Little League bases are only 60 feet apart. Why do you think kids' fields are smaller?","peek":"Kids are smaller/slower and can't throw as far; keeps the game fair and fun.","clue":"Could a 7-year-old throw from third base to first on a big-league field?"}]},
    {"id":"baseball-012","q":"What is a 'bunt'?","c":["Tapping the ball softly without a full swing","A huge home run","A pitch that curves","A catcher's mitt"],"skill":"rules","why":"A bunt is a soft tap so the ball rolls just a little way into the infield.","hint":"It's the opposite of a big swing — the batter holds the bat out and just taps it.","deeper":[{"t":"mc","k":"more","q":"A 'sacrifice bunt' often gets the batter out. Why do it?","c":["To move a teammate to the next base","To rest","To get a walk","To end the game"],"why":"The batter gives up an out so a teammate can move closer to home."},{"t":"talk","k":"more","q":"When might a sneaky bunt surprise the fielders?","peek":"When fielders are playing far back expecting a big hit; a fast runner can beat the throw.","clue":"Where are the fielders standing if they expect a big hit?"}]},
    {"id":"baseball-013","q":"Which team bats first in a baseball game?","c":["The visiting (away) team","The home team","Whoever is taller","The team with the most fans"],"skill":"rules","why":"The visitors bat first, in the 'top' of each inning. The home team bats in the 'bottom'.","hint":"The home team gets to bat LAST — so who goes first?","deeper":[{"t":"mc","k":"more","q":"The home team bats in which half of each inning?","c":["The bottom","The top","The middle","Neither"],"why":"The bottom half!"},{"t":"talk","k":"whatif","q":"If the home team is winning after the top of the 9th, they don't need to bat. Why not?","peek":"They're already ahead and the visitors have no more turns, so the game is over.","clue":"Can the visitors score any more runs after their last turn?"}]},
    {"id":"baseball-014","q":"What colour is the stitching on an official baseball?","c":["Red","Blue","Green","Gold"],"skill":"rules","why":"Red! There are 108 double stitches on every MLB baseball, sewn by hand.","hint":"Picture a white ball with stitches the colour of a stop sign.","deeper":[{"t":"mc","k":"more","q":"The stitches help pitchers grip the ball. What does that let them do?","c":["Make the ball spin and curve","Make it glow","Make it heavier","Make it bounce"],"why":"Gripping the seams helps pitchers spin the ball to make curves and sliders."},{"t":"mc","k":"more","q":"There are 108 double stitches. That's how many single stitches?","c":["216","108","54","200"],"why":"108 × 2 = 216.","hint":"Double means two of each. What's 108 + 108?"}]},
    {"id":"baseball-015","q":"What is at the very centre of a baseball?","c":["A cork and rubber core","Air","A marble","Sand"],"skill":"rules","why":"A small cork core wrapped in rubber, then lots of yarn, then a leather cover.","hint":"It's a light, springy material — the same stuff in bottle stoppers.","deeper":[{"t":"mc","k":"more","q":"What covers the outside of a baseball?","c":["Leather","Plastic","Paper","Rubber bands"],"why":"Leather (cowhide)!"},{"t":"talk","k":"whatif","q":"Predict: would a ball with a heavy metal centre go farther or shorter when you hit it? Why?","peek":"Heavier ball is harder to hit far/would hurt; it wouldn't bounce off the bat as much.","clue":"Is a heavy thing easier or harder to throw far?"}]},
    {"id":"baseball-016","q":"A fly ball caught before it touches the ground means the batter is…","c":["Out","Safe","On second base","Given a home run"],"skill":"rules","why":"Out! A catch in the air is called a 'fly out'.","hint":"If the fielder catches it in the air, does the batter get on base?","deeper":[{"t":"mc","k":"whatif","q":"If a fielder drops an easy catch, it's often called an…","c":["Error","Assist","Ace","Strike"],"why":"An error!"},{"t":"talk","k":"why","q":"Why do fielders use two hands to catch a fly ball when they can?","peek":"More secure — the second hand traps the ball so it doesn't pop out.","clue":"Which is easier to drop: something you hold with one hand or two?"}]},
    {"id":"baseball-017","q":"If a batter hits a foul ball with 0 or 1 strikes, it counts as a…","c":["Strike","Ball","Home run","Out"],"skill":"rules","why":"A strike! But with 2 strikes, a regular foul ball can't strike you out.","hint":"Is a foul ball good for the batter or the pitcher?","deeper":[{"t":"mc","k":"more","q":"The batter has 2 strikes and hits a foul ball. What happens?","c":["The count stays at 2 strikes","Strike three — out!","They walk","It's a home run"],"why":"Still 2 strikes — a normal foul can't be strike three."},{"t":"talk","k":"why","q":"Why might a smart batter try to foul off tough pitches with 2 strikes?","peek":"Stays alive; tires the pitcher; waits for a better pitch to hit.","clue":"If a foul can't strike you out, what do you get by fouling one off?"}]},
    {"id":"baseball-018","q":"Who calls balls and strikes in a baseball game?","c":["The home plate umpire","The pitcher","The fans","The shortstop"],"skill":"rules","why":"The home plate umpire, crouching behind the catcher.","hint":"This official stands right behind the catcher.","deeper":[{"t":"mc","k":"why","q":"Why does the umpire stand behind the catcher?","c":["To see where each pitch crosses the plate","To get shade","To catch foul balls for fans","To coach"],"why":"So they can see if the pitch goes through the strike zone."},{"t":"talk","k":"more","q":"Umpires sometimes make mistakes. How should players act when they disagree with a call?","peek":"Stay respectful, ask calmly, move on; arguing can get you thrown out.","clue":"What happens if a player yells at the umpire?"}]},
    {"id":"baseball-019","q":"What is a 'stolen base'?","c":["Running to the next base while the pitcher pitches","Taking a base home","Hiding a base","Hitting a home run"],"skill":"rules","why":"A stolen base is when a runner dashes to the next base during a pitch — and makes it!","hint":"The runner goes to the next base without a hit… sneaky like a thief!","deeper":[{"t":"mc","k":"more","q":"Which base is stolen most often?","c":["Second base","Home plate","First base","Third base"],"why":"Second base! It's the farthest from the catcher's throw."},{"t":"talk","k":"why","q":"Why is second base easier to steal than home?","peek":"The catcher's throw to second is long; stealing home means running right at the catcher with the ball.","clue":"Where is the catcher standing?"}]},
    {"id":"baseball-020","q":"Which player stands between second base and third base?","c":["Shortstop","Catcher","Pitcher","Right fielder"],"skill":"rules","why":"The shortstop! It's one of the busiest positions on the field.","hint":"Their name sounds like they stop things — but it's not the catcher.","deeper":[{"t":"mc","k":"more","q":"The infielders are first base, second base, third base and…","c":["Shortstop","Goalie","Pitcher","Left field"],"why":"Shortstop — four infielders in all."},{"t":"talk","k":"more","q":"Lots of balls are hit to the shortstop. Why do you think teams put a great fielder there?","peek":"Many right-handed batters hit to that side; long throw to first needs a strong arm.","clue":"Most batters are right-handed — which side do they usually hit toward?"}]},
    {"id":"baseball-021","q":"What is the 'bullpen'?","c":["Where relief pitchers warm up","Where bulls live","The dugout","The scoreboard"],"skill":"rules","why":"The bullpen is where relief pitchers warm up before coming into the game.","hint":"It's where the extra pitchers get ready.","deeper":[{"t":"mc","k":"more","q":"A pitcher who comes in to replace the starting pitcher is a…","c":["Reliever","Rookie","Referee","Rebounder"],"why":"A relief pitcher (reliever)!"},{"t":"talk","k":"why","q":"Why would a team change pitchers during a game?","peek":"Starter gets tired, is hit hard, or a specialist is better against certain batters.","clue":"How does your arm feel after throwing 100 times?"}]},
    {"id":"baseball-022","q":"What does 'RBI' stand for?","c":["Runs Batted In","Really Big Inning","Run, Bat, Inning","Running Back Inside"],"skill":"rules","why":"Runs Batted In — a batter gets an RBI when their hit (or walk etc.) brings a teammate home.","hint":"The batter BATS a teammate IN to score.","deeper":[{"t":"mc","k":"more","q":"Bases loaded and the batter hits a grand slam. How many RBIs?","c":["4","1","3","0"],"why":"All 4 runs count as RBIs!","hint":"Three runners plus the batter — how many cross home?"},{"t":"talk","k":"why","q":"Why does a batter get credit when a TEAMMATE scores?","peek":"Their hit is what let the teammate get home.","clue":"Could the runner have scored without the hit?"}]},
    {"id":"baseball-023","q":"The World Series is between the champions of the American League and the…","c":["National League","Canadian League","World League","Little League"],"skill":"teams","why":"The National League! The two league champions meet in the World Series.","hint":"There are two leagues: American and N_______.","deeper":[{"t":"mc","k":"more","q":"The Blue Jays play in which league?","c":["American League","National League","Little League","Hockey League"],"why":"The American League!"},{"t":"mc","k":"more","q":"The World Series is 'best of 7'. How many wins does a team need?","c":["4","7","3","5"],"why":"4 wins — more than half of 7.","hint":"What's the smallest number of wins that's more than half of 7?"}]},
    {"id":"baseball-024","q":"Which Canadian city used to have an MLB team called the Expos?","c":["Montreal","Vancouver","Halifax","Regina"],"skill":"teams","why":"Montreal! The Expos played from 1969 to 2004, then moved and became the Washington Nationals.","hint":"The team was named after Expo 67, a world's fair in a big Quebec city.","deeper":[{"t":"mc","k":"more","q":"The Expos were named after 'Expo 67', a world's fair held in Montreal in…","c":["1967","1867","2007","1767"],"why":"1967 — Canada's 100th birthday year!"},{"t":"talk","k":"more","q":"When a team moves away, how do you think its fans feel? What could a city do to keep a team?","peek":"Sad/upset; build a new stadium, buy tickets, support it.","clue":"How would you feel if your favourite team moved away?"}]},
    {"id":"baseball-025","q":"Babe Ruth hit his very first professional home run in 1914 in which city?","c":["Toronto","New York","Boston","Chicago"],"skill":"teams","why":"Toronto! At Hanlan's Point on the Toronto Islands, while playing in the minor leagues.","hint":"It was a Canadian city — the same one the Blue Jays play in today.","deeper":[{"t":"mc","k":"more","q":"Babe Ruth was most famous for…","c":["Hitting home runs","Stealing bases","Being a goalie","Umpiring"],"why":"Hitting home runs — 714 in the majors!"},{"t":"talk","k":"more","q":"Ruth started as a pitcher, then became a hitter. Why might a team move a great hitter out of pitching?","peek":"So he can play (and hit) every day; pitchers only play every few days.","clue":"How often does a pitcher play compared to an outfielder?"}]},
    {"id":"baseball-026","q":"Ferguson Jenkins was the first Canadian in the Baseball Hall of Fame. What position did he play?","c":["Pitcher","Catcher","Shortstop","Umpire"],"skill":"teams","why":"Pitcher! 'Fergie' Jenkins from Chatham, Ontario, joined the Hall of Fame in 1991.","hint":"He threw the ball from the mound.","deeper":[{"t":"mc","k":"more","q":"Jenkins is from Chatham in which province?","c":["Ontario","Alberta","Quebec","Nova Scotia"],"why":"Ontario!"},{"t":"talk","k":"more","q":"Jenkins also played hockey and basketball as a kid. How might playing many sports help an athlete?","peek":"Builds different skills, strength, coordination; less burnout; more fun.","clue":"What skills from hockey could help in baseball?"}]},
    {"id":"baseball-027","q":"Larry Walker, a Hall of Fame hitter, grew up in which province?","c":["British Columbia","Manitoba","PEI","Nova Scotia"],"skill":"teams","why":"British Columbia (Maple Ridge)! As a kid he dreamed of being a hockey goalie.","hint":"It's Canada's westernmost province, on the Pacific.","deeper":[{"t":"mc","k":"more","q":"Larry Walker joined the Baseball Hall of Fame in…","c":["2020","1920","1867","2000"],"why":"2020!"},{"t":"talk","k":"more","q":"Walker didn't play much baseball until he was a teenager — and still became a star. What does that teach you?","peek":"It's never too late to start; practice and hard work matter.","clue":"Do you have to start something as a little kid to become great?"}]},
    {"id":"baseball-028","q":"The Little League World Series is played every summer in which country?","c":["USA (Pennsylvania)","Japan","Mexico","Canada"],"skill":"teams","why":"Williamsport, Pennsylvania, USA. Teams of kids come from all over the world — including Canada!","hint":"It's in the country just south of Canada.","deeper":[{"t":"mc","k":"more","q":"Little League players are usually about what age?","c":["10 to 12","20 to 25","2 to 4","30 to 40"],"why":"About 10 to 12 years old!"},{"t":"talk","k":"whatif","q":"If you played on TV in front of millions of people, how would you stay calm?","peek":"Breathe, focus on the next pitch, have fun, trust teammates.","clue":"What helps you calm down before something big?"}]},
    {"id":"baseball-029","q":"A pitch that bends as it goes toward the plate is called a…","c":["Curveball","Straightball","Snowball","Fastball"],"skill":"rules","why":"A curveball! The pitcher spins the ball so it curves or drops.","hint":"It doesn't go straight — it CURVES.","deeper":[{"t":"mc","k":"more","q":"What makes a curveball curve?","c":["Spin on the ball","Wind from fans","A magnet","The bat"],"why":"Spin! The spinning ball pushes on the air and bends its path."},{"t":"talk","k":"why","q":"Why is a pitch that changes direction hard to hit?","peek":"Batter has to guess where it'll be; it moves after they start swinging.","clue":"When do you decide where to swing — before or after the ball arrives?"}]},
    {"id":"baseball-030","q":"In baseball, a 'shutout' means…","c":["One team scored zero runs","The stadium is closed","It rained","The game went extra innings"],"skill":"rules","why":"A shutout means the other team didn't score a single run!","hint":"The pitcher 'shut out' the other team — how many runs did they score?","deeper":[{"t":"mc","k":"more","q":"Final score 5–0. Which team got shut out?","c":["The team with 0","The team with 5","Both","Neither"],"why":"The team with 0 runs!"},{"t":"talk","k":"more","q":"Is a shutout only the pitcher's job? Who else helps?","peek":"Fielders make plays/catches, catcher calls pitches — it's a team effort.","clue":"Who catches the balls that batters hit?"}]},
    {"id":"baseball-031","q":"What is a 'perfect game'?","c":["No batter from the other team reaches base","Everyone hits a home run","The game ends 0–0","Nobody strikes out"],"skill":"rules","why":"A perfect game: 27 batters up, 27 down — no hits, no walks, nobody on base. It's super rare!","hint":"PERFECT means not one single batter gets on base…","deeper":[{"t":"mc","k":"more","q":"In a perfect game, how many batters does the pitching team face in 9 innings?","c":["27","9","30","18"],"why":"3 per inning × 9 innings = 27 batters.","hint":"3 outs per inning, 9 innings: 3 × 9 = ?"},{"t":"talk","k":"more","q":"A 'no-hitter' allows no hits but might allow walks. Why is a perfect game even harder?","peek":"Perfect also allows no walks, errors, or hit batters — absolutely nobody on base.","clue":"What's one way to reach base WITHOUT a hit?"}]},
    {"id":"baseball-032","q":"What does the 'designated hitter' (DH) do?","c":["Bats instead of the pitcher","Pitches only","Coaches first base","Sells hot dogs"],"skill":"rules","why":"The DH bats in place of the pitcher. Since 2022, both MLB leagues use it.","hint":"Pitchers often aren't great hitters… so who could bat for them?","deeper":[{"t":"mc","k":"why","q":"Why did leagues want a DH?","c":["Pitchers are usually weak hitters","Pitchers are too tall","DHs are cheaper","To make games shorter"],"why":"Most pitchers practise pitching, not hitting!"},{"t":"talk","k":"more","q":"Is it fair that one player only bats and never fields? Give a reason for your opinion.","peek":"Either side with a reason: more offence/fun vs. everyone should play both.","clue":"What's good about it? What's not?"}]},
    {"id":"baseball-033","q":"Boston's Fenway Park has a famous tall left-field wall nicknamed…","c":["The Green Monster","The Blue Giant","The Big Fence","The Red Wall"],"skill":"teams","why":"The Green Monster! It's about 11 metres (37 feet) tall.","hint":"It's green and huge and a little scary…","deeper":[{"t":"mc","k":"more","q":"A tall wall close to home plate makes it harder to hit a…","c":["Home run over it","Bunt","Walk","Strikeout"],"why":"Home run — the ball must go high to clear it."},{"t":"talk","k":"why","q":"Why might a hitter hit lots of doubles off a big wall instead of home runs?","peek":"The ball hits the wall and bounces back; runner gets to second.","clue":"What happens when the ball hits the wall instead of going over?"}]},
    {"id":"baseball-034","q":"The outfield walls at Chicago's Wrigley Field are covered in…","c":["Ivy (green vines)","Ice","Posters","Mirrors"],"skill":"teams","why":"Ivy! The vines were planted in 1937.","hint":"It's a green plant that climbs walls.","deeper":[{"t":"mc","k":"more","q":"Wrigley Field is home to which team?","c":["Chicago Cubs","Toronto Blue Jays","New York Yankees","Boston Red Sox"],"why":"The Chicago Cubs!"},{"t":"talk","k":"whatif","q":"If a ball gets stuck in the ivy, what do you think the rule should be? Why?","peek":"Fair answer with reasoning (it's a ground-rule double in real life).","clue":"Should the batter get a home run, or something less?"}]},
    {"id":"baseball-035","q":"The New York Yankees play in which city?","c":["New York","Boston","Toronto","Los Angeles"],"skill":"teams","why":"New York! The Yankees have won more World Series than any other team.","hint":"It's right in their name!","deeper":[{"t":"mc","k":"more","q":"Blue Jays vs. Yankees is a rivalry because they play in the same…","c":["Division","City","Country","Stadium"],"why":"Same division — they play each other a lot!"},{"t":"talk","k":"why","q":"Why do teams that play each other often become rivals?","peek":"Lots of games, competing for the same playoff spot, history.","clue":"If you played the same team many times, how would you feel?"}]},
    {"id":"baseball-036","q":"Hank Aaron is famous for passing Babe Ruth's record for career…","c":["Home runs","Strikeouts","Stolen bases","Wins as a pitcher"],"skill":"teams","why":"Home runs! In 1974 he hit number 715 and finished his career with 755.","hint":"Babe Ruth was famous for hitting balls over the fence…","deeper":[{"t":"mc","k":"more","q":"Ruth had 714 home runs. Aaron's record-breaker was number…","c":["715","714","700","800"],"why":"715 — one more than 714!"},{"t":"talk","k":"more","q":"Aaron received mean letters because of his race while chasing the record, but kept going. What does that tell you about him?","peek":"Courage, strength, focus, not letting hate stop him.","clue":"How hard would it be to keep playing well while people were mean?"}]},
    {"id":"baseball-037","q":"A team scores 2 runs in the 1st inning, 3 in the 5th and 1 in the 9th. How many runs in total?","c":["6","5","7","4"],"skill":"math","why":"2 + 3 + 1 = 6 runs!","hint":"Add them one at a time: 2 + 3 first, then add 1.","deeper":[{"t":"mc","k":"more","q":"The other team scored 4. Who won, and by how many?","c":["The first team, by 2","The other team, by 2","Tie","The first team, by 10"],"why":"6 − 4 = 2. The first team won by 2!","hint":"Which is bigger, 6 or 4? Then subtract."},{"t":"talk","k":"more","q":"Make up your own baseball score story with three innings — what's the total?","peek":"Any correct addition story.","clue":"Pick three small numbers and add them."}]},
    {"id":"baseball-038","q":"The score is 4 to 2. How many runs does the losing team need just to TIE?","c":["2","4","1","6"],"skill":"math","why":"4 − 2 = 2 runs to tie (and 3 to take the lead).","hint":"How far apart are 2 and 4?","deeper":[{"t":"mc","k":"more","q":"How many runs do they need to take the LEAD?","c":["3","2","4","1"],"why":"3 runs makes it 5 to 4!"},{"t":"talk","k":"why","q":"Why do you think teams play extra carefully when the game is close?","peek":"One mistake/one run can decide the game.","clue":"When the score is close, how much does one run matter?"}]},
    {"id":"baseball-039","q":"A pitcher throws 15 pitches each inning for 6 innings. How many pitches?","c":["90","60","21","100"],"skill":"math","why":"15 × 6 = 90 pitches. (10 × 6 = 60, plus 5 × 6 = 30.)","hint":"Split it: 10 × 6 and 5 × 6, then add.","deeper":[{"t":"mc","k":"whatif","q":"If the pitcher stops at 100 pitches, how many more could they throw after 90?","c":["10","100","9","20"],"why":"100 − 90 = 10."},{"t":"talk","k":"more","q":"Teams count pitches to protect pitchers' arms. Why do kids' leagues have pitch limits too?","peek":"Young arms can get hurt from throwing too much.","clue":"What happens to muscles if you overuse them?"}]},
    {"id":"baseball-040","q":"A lineup has 9 batters. After batter #9 hits, who bats next?","c":["Batter #1","Batter #10","Batter #9 again","The pitcher"],"skill":"math","why":"Back to the top — batter #1! The order keeps looping around.","hint":"There is no batter #10… so where does the list start again?","deeper":[{"t":"mc","k":"more","q":"In one inning, batters #1 to #9 all bat, then #1 and #2 bat again. How many times did someone bat?","c":["11","9","10","12"],"why":"9 + 2 = 11 plate appearances!","hint":"Count the first 9, then add the 2 extra."},{"t":"talk","k":"why","q":"Why do coaches put their best hitters near the top of the lineup?","peek":"They get to bat more times over the game.","clue":"Who bats more often in a game — #1 or #9?"}]},
    {"id":"baseball-041","q":"Hits: a single = 1 base, a double = 2, a triple = 3. One player hits all three. How many total bases?","c":["6","3","5","4"],"skill":"math","why":"1 + 2 + 3 = 6 total bases!","hint":"Add 1 + 2 first, then add 3.","deeper":[{"t":"mc","k":"more","q":"A home run counts as how many bases?","c":["4","1","3","5"],"why":"4 — all the way around!"},{"t":"mc","k":"more","q":"Getting a single, double, triple AND home run in one game is called…","c":["Hitting for the cycle","A hat trick","A grand slam","A perfect game"],"why":"Hitting for the cycle — very rare!"}]},
    {"id":"baseball-042","q":"27 outs are needed in a 9-inning game. A team has made 18 outs. How many innings have been played?","c":["6","9","18","3"],"skill":"math","why":"18 ÷ 3 = 6 innings (3 outs each).","hint":"Each inning has 3 outs. Count by 3s until you reach 18.","deeper":[{"t":"mc","k":"more","q":"How many innings are left?","c":["3","6","9","2"],"why":"9 − 6 = 3 innings."},{"t":"talk","k":"more","q":"Explain how counting by 3s helped you solve this.","peek":"3, 6, 9, 12, 15, 18 = 6 jumps → 6 innings.","clue":"How many jumps of 3 to get to 18?"}]},
    {"id":"baseball-043","q":"What do you call a hit where the batter safely runs all the way to third base?","c":["A triple","A double","A single","A grand slam"],"skill":"rules","why":"A triple! Triples are rare because the ball has to go far AND the batter has to be fast.","hint":"Single = 1, double = 2, and 3 = ?","deeper":[{"t":"mc","k":"why","q":"Why are triples rarer than doubles?","c":["You need a long hit AND lots of speed","They're against the rules","Only pitchers hit them","They count as outs"],"why":"You need distance and speed!"},{"t":"talk","k":"more","q":"What kind of player do you think hits the most triples — a big slow slugger or a fast runner? Why?","peek":"A fast runner — they can reach third before the throw.","clue":"Who gets around the bases quicker?"}]},
    {"id":"baseball-044","q":"What is a 'walk-off' hit?","c":["A hit by the home team that wins the game instantly","A hit while walking","A foul ball","A hit in the first inning"],"skill":"rules","why":"A walk-off ends the game right away — the other team just walks off the field!","hint":"It happens in the last inning, and the losing team has to walk off the field…","deeper":[{"t":"mc","k":"more","q":"Only which team can get a walk-off?","c":["The home team","The visiting team","Either","Neither"],"why":"The home team — they bat last!"},{"t":"talk","k":"why","q":"Why can't the visiting team ever get a 'walk-off'?","peek":"The home team always gets its last turn after them, so the game isn't over.","clue":"After the visitors bat in the 9th, who still gets to bat?"}]},
    {"id":"baseball-045","q":"How far is it from the pitcher's rubber to home plate in MLB?","c":["60 feet 6 inches","90 feet","30 feet","100 feet"],"skill":"rules","why":"60 feet, 6 inches (about 18.4 metres)! A 150 km/h fastball gets there in less than half a second.","hint":"It's less than the 90 feet between bases.","deeper":[{"t":"mc","k":"more","q":"Which is longer: base to base, or pitcher to home?","c":["Base to base (90 ft)","Pitcher to home","Same","Neither"],"why":"90 feet is longer than 60 feet 6 inches."},{"t":"talk","k":"more","q":"A fastball reaches the plate in less than half a second. How do batters ever hit it?","peek":"Practice, watching the pitcher's hand, predicting the pitch, quick reactions.","clue":"Do batters decide to swing before or after the ball is halfway?"}]},
    {"id":"baseball-046","q":"Why does the catcher wiggle fingers between their knees before a pitch?","c":["To signal which pitch to throw","To stay warm","To say hello","To scratch an itch"],"skill":"rules","why":"Secret signals! The fingers tell the pitcher which pitch to throw.","hint":"It's a secret code between two teammates…","deeper":[{"t":"mc","k":"why","q":"Why hide the signals between the knees?","c":["So the other team can't see","It's the rules","To look cool","To keep fingers clean"],"why":"So the batter and other team can't read them!"},{"t":"talk","k":"whatif","q":"Make up a secret signal system for your family. How would you keep it secret?","peek":"Any creative code with a reason for secrecy.","clue":"What could 1 finger, 2 fingers mean?"}]},
    {"id":"baseball-047","q":"Which of these is NOT a baseball position?","c":["Goalie","Pitcher","Shortstop","Catcher"],"skill":"rules","why":"Goalie — that's for hockey or soccer!","hint":"Three of these are on a baseball diamond. Which one stands in front of a net?","deeper":[{"t":"mc","k":"more","q":"Which of these IS a baseball position?","c":["Centre fielder","Left winger","Point guard","Quarterback"],"why":"Centre fielder!"},{"t":"talk","k":"more","q":"Hockey has a goalie; baseball has a catcher. How are their jobs alike?","peek":"Both crouch, catch fast things, wear lots of gear, see the whole field.","clue":"What gear do both wear?"}]},
    {"id":"baseball-048","q":"Four balls is a walk. The pitcher has thrown 2 balls. How many more for a walk?","c":["2","4","1","3"],"skill":"math","why":"4 − 2 = 2 more balls.","hint":"Count up from 2 to 4.","deeper":[{"t":"mc","k":"more","q":"The count is 3 balls and 2 strikes (a 'full count'). How many more balls for a walk?","c":["1","2","3","0"],"why":"Just 1!"},{"t":"talk","k":"more","q":"With a full count, the next pitch could decide everything. Who is under more pressure — the pitcher or the batter? Why?","peek":"Either with a reason: pitcher must throw a strike; batter could strike out.","clue":"What happens if the pitcher throws one more ball?"}]},
    {"id":"baseball-049","q":"The Blue Jays' mascot is a big blue bird named…","c":["Ace","Tim","Rocky","Sparky"],"skill":"teams","why":"Ace! He's been cheering at Jays games since 2000.","hint":"It's a word for a great pitcher, and for a top playing card.","deeper":[{"t":"mc","k":"more","q":"In baseball, an 'ace' is a team's…","c":["Best starting pitcher","Mascot only","Shortest player","Coach"],"why":"The team's best starting pitcher!"},{"t":"talk","k":"whatif","q":"If you designed a mascot for your favourite team, what would it be, and why?","peek":"Any creative mascot with a reason.","clue":"What animal or thing fits the team's name?"}]},
    {"id":"baseball-050","q":"Jackie Robinson's first pro team in 1946 was the Montreal Royals. Which MLB team called him up in 1947?","c":["Brooklyn Dodgers","Toronto Blue Jays","Montreal Expos","Boston Red Sox"],"skill":"teams","why":"The Brooklyn Dodgers! (They later moved to Los Angeles.)","hint":"It was a team in New York City that later moved to Los Angeles.","deeper":[{"t":"mc","k":"why","q":"Why were Montreal fans important to Jackie Robinson in 1946?","c":["They cheered and welcomed him","They booed him","They didn't watch","They chose his number"],"why":"Montreal fans cheered and supported him."},{"t":"talk","k":"why","q":"Why can kindness from fans make a big difference to a player facing unfair treatment?","peek":"Feels supported, not alone, more confident.","clue":"How does it feel when people cheer for you?"}]},
    {"id":"baseball-051","q":"A pitch that misses the strike zone and the batter doesn't swing is called a…","c":["Ball","Strike","Foul","Homer"],"skill":"rules","why":"A ball! Four balls and the batter walks to first base.","hint":"It's the opposite of a strike…","deeper":[{"t":"mc","k":"more","q":"Four balls lets the batter…","c":["Walk to first base","Go home","Sit down","Pitch"],"why":"A walk!"},{"t":"talk","k":"why","q":"Why might a pitcher throw a ball on purpose sometimes?","peek":"To get the batter to chase a bad pitch; to avoid a great hitter.","clue":"Would you swing at a pitch way outside?"}]},
    {"id":"baseball-052","q":"The 'strike zone' is roughly between the batter's…","c":["Knees and chest","Toes and ankles","Head and sky","Elbows and fingers"],"skill":"rules","why":"From about the knees up to the middle of the chest, over home plate!","hint":"Picture a box over the plate — from where to where on the body?","deeper":[{"t":"mc","k":"more","q":"Does a tall batter have a bigger or smaller strike zone?","c":["Bigger","Smaller","Same","No zone"],"why":"Bigger — the zone grows with the batter!"},{"t":"talk","k":"why","q":"Why do some batters crouch down low?","peek":"To make their strike zone smaller.","clue":"What happens to the knees-to-chest space when you crouch?"}]},
    {"id":"baseball-053","q":"What does the umpire shout to start a game?","c":["\"Play ball!\"","\"Go!\"","\"Ready, set!\"","\"Batter down!\""],"skill":"rules","why":"\"Play ball!\"","hint":"It's two words, and the second one is the thing you throw!","deeper":[{"t":"mc","k":"more","q":"What does an umpire usually signal for an out?","c":["A fist punch or thumb up","Two thumbs down","A wave","A bow"],"why":"A punch or 'you're out!' sign!"},{"t":"talk","k":"why","q":"Why do umpires use big hand signals instead of just talking?","peek":"Players and fans far away can see the call.","clue":"Can people in the top row hear the ump?"}]},
    {"id":"baseball-054","q":"Where do players sit when they're not on the field?","c":["The dugout","The bullpen","The penalty box","The press box"],"skill":"rules","why":"The dugout! It's often dug a little below the field — that's the name!","hint":"It's 'dug' into the ground…","deeper":[{"t":"mc","k":"more","q":"Where do relief pitchers warm up?","c":["The bullpen","The dugout","The parking lot","Home plate"],"why":"The bullpen!"},{"t":"talk","k":"why","q":"Why do you think dugouts are lower than the field?","peek":"So fans behind can see over them; protection.","clue":"What would fans see if the bench were tall?"}]},
    {"id":"baseball-055","q":"The strip of dirt in front of the outfield wall is called the…","c":["Warning track","Base path","Infield","Batter's box"],"skill":"rules","why":"The warning track! The crunchy dirt warns fielders that the wall is close.","hint":"It WARNS fielders that something is coming…","deeper":[{"t":"mc","k":"why","q":"Why does an outfielder need a warning?","c":["So they don't crash into the wall","To slow the ball","To find water","To look pretty"],"why":"Safety!"},{"t":"talk","k":"whatif","q":"If you're running back for a fly ball looking up, how could your feet 'tell' you where you are?","peek":"Feel the change from grass to dirt.","clue":"What do your feet notice when the ground changes?"}]},
    {"id":"baseball-056","q":"If a fly ball hits the yellow foul pole, is it fair or foul?","c":["Fair — it's a home run!","Foul","Do-over","An out"],"skill":"rules","why":"Fair! The 'foul pole' is actually in fair territory — a funny name!","hint":"Surprise — the name is backwards!","deeper":[{"t":"mc","k":"why","q":"Why is the name 'foul pole' confusing?","c":["It marks the line but counts as fair","It's purple","It's in the dugout","It's for fouls only"],"why":"It's a fair pole really!"},{"t":"talk","k":"whatif","q":"If you could rename the foul pole, what would you call it?","peek":"Any creative name (fair pole, home-run pole).","clue":"What happens when the ball hits it?"}]},
    {"id":"baseball-057","q":"Why do batters and base runners wear helmets?","c":["To protect their heads from the hard ball","To look tall","To keep warm","For the rain"],"skill":"rules","why":"Safety! A pitched baseball is hard and fast.","hint":"What part of the body needs the most protection?","deeper":[{"t":"mc","k":"more","q":"Most batting helmets have a flap that covers…","c":["The ear facing the pitcher","The nose","The chin only","The back of the neck"],"why":"The ear facing the pitcher!"},{"t":"talk","k":"why","q":"Why is the ear flap on the side facing the pitcher?","peek":"That's where a wild pitch would hit.","clue":"Which way does the ball come from?"}]},
    {"id":"baseball-058","q":"To get a runner out who is not on a base, a fielder can…","c":["Tag them with the ball","Yell at them","Trip them","Wave"],"skill":"rules","why":"Tag them with the ball (or the glove holding it)!","hint":"The fielder touches them while holding something…","deeper":[{"t":"mc","k":"more","q":"A 'force out' happens when a fielder with the ball…","c":["Steps on the base the runner must reach","Hugs the runner","Throws it away","Drops it"],"why":"Steps on the base first!"},{"t":"talk","k":"why","q":"Why does a runner slide into a base?","peek":"To get there fast without overrunning it and dodge tags.","clue":"Can you stop running at full speed exactly on a bag?"}]},
    {"id":"baseball-059","q":"Which fielders usually wear a big round padded 'mitt' instead of a regular glove?","c":["Catcher and first baseman","Shortstop and left fielder","Pitcher and umpire","Batters"],"skill":"rules","why":"The catcher and first baseman — they catch the most throws!","hint":"Who catches lots and lots of balls every game?","deeper":[{"t":"mc","k":"more","q":"What else does a catcher wear for protection?","c":["Mask, chest protector and shin guards","Skates","Swim goggles","A cape"],"why":"The 'tools of ignorance'!"},{"t":"talk","k":"why","q":"Why does a catcher need more protection than an outfielder?","peek":"Fast pitches and foul tips, bats swinging nearby.","clue":"Who is closest to the batter?"}]},
    {"id":"baseball-060","q":"Major League bats must be made of…","c":["Wood (like maple or ash)","Metal","Plastic","Glass"],"skill":"rules","why":"Wood! Kids' and college games often use metal (aluminum) bats.","hint":"It comes from trees…","deeper":[{"t":"mc","k":"more","q":"Many big-league bats are made from which tree that's also on Canada's flag?","c":["Maple","Palm","Pine","Oak"],"why":"Maple!"},{"t":"talk","k":"why","q":"Why do you think the pros use wood instead of metal bats?","peek":"Metal bats hit harder/farther — safer and keeps records fair; tradition.","clue":"Which bat makes the ball go faster?"}]},
    {"id":"baseball-061","q":"A 'switch hitter' is a batter who…","c":["Can bat both left- and right-handed","Changes teams","Switches bats every pitch","Bats twice"],"skill":"rules","why":"They can bat from both sides of the plate!","hint":"They switch which side they stand on…","deeper":[{"t":"mc","k":"why","q":"Why switch sides? Batters often see the ball better against a pitcher who throws with the…","c":["Opposite hand","Same hand","Left foot","Glove"],"why":"Opposite hand — the ball curves toward you!"},{"t":"talk","k":"more","q":"Try a pretend swing on your other side. How does it feel? Why is switch hitting hard?","peek":"Awkward; needs lots of practice; muscles learn one way.","clue":"Is writing with your other hand easy?"}]},
    {"id":"baseball-062","q":"Starting in 2023, MLB added a timer to make games faster. What's it called?","c":["The pitch clock","The egg timer","The sun dial","The bat clock"],"skill":"rules","why":"The pitch clock! Pitchers have a short time to throw, and games got about 25 minutes shorter.","hint":"It's a clock for the person who throws…","deeper":[{"t":"mc","k":"whatif","q":"If a pitcher takes too long with the pitch clock, the batter gets a…","c":["Ball","Strike","Home run","Hot dog"],"why":"An automatic ball!"},{"t":"talk","k":"more","q":"Do you think the pitch clock is a good idea? Why or why not?","peek":"Either view with a reason (faster vs. less thinking time).","clue":"Do long games get boring or exciting?"}]},
    {"id":"baseball-063","q":"How many sides does home plate have?","c":["5 (it's a pentagon)","4","3","8"],"skill":"rules","why":"5! Home plate is a pentagon — like a little house shape.","hint":"It looks like a house drawn with a pointy roof.","deeper":[{"t":"mc","k":"more","q":"The other bases are shaped like…","c":["Squares","Circles","Triangles","Stars"],"why":"Squares!"},{"t":"talk","k":"why","q":"Why do you think the umpire brushes home plate clean?","peek":"So everyone can see the plate to call strikes.","clue":"What can't the ump see if it's covered in dirt?"}]},
    {"id":"baseball-064","q":"In baseball scorekeeping, each position has a number. Which number is the shortstop?","c":["6","1","2","9"],"skill":"rules","why":"6! Pitcher 1, catcher 2, first 3, second 4, third 5, shortstop 6, then left, centre, right are 7, 8, 9.","hint":"Pitcher is 1, catcher is 2… the infield goes 3, 4, 5, then the sneaky one…","deeper":[{"t":"mc","k":"more","q":"So a '6-4-3 double play' goes shortstop to…","c":["Second base to first base","Catcher to pitcher","Left to right","Home to third"],"why":"Short → second → first!"},{"t":"talk","k":"why","q":"Why would scorekeepers use numbers instead of writing names?","peek":"Faster and shorter to write.","clue":"How long does it take to write 'shortstop'?"}]},
    {"id":"baseball-065","q":"A 'knuckleball' is a slow pitch that…","c":["Wobbles and dances because it barely spins","Goes 200 km/h","Is thrown underhand","Rolls on the ground"],"skill":"rules","why":"It barely spins, so air pushes it around in wobbly, unpredictable ways!","hint":"Think about what happens when a ball doesn't spin…","deeper":[{"t":"mc","k":"more","q":"Which knuckleball pitcher won the Cy Young Award (best pitcher) in 2012, then joined the Blue Jays?","c":["R.A. Dickey","Babe Ruth","Jackie Robinson","Joe Carter"],"why":"R.A. Dickey!"},{"t":"talk","k":"why","q":"Why might a catcher find a knuckleball hard to catch too?","peek":"Nobody knows where it'll go, not even the pitcher.","clue":"If the pitcher can't predict it, can the catcher?"}]},
    {"id":"baseball-066","q":"A pitcher who comes in to get the last outs of a close game is called the…","c":["Closer","Opener","Doorman","Finisher-upper"],"skill":"rules","why":"The closer! They 'close' the door on the other team.","hint":"They 'close' the game…","deeper":[{"t":"mc","k":"more","q":"A pitcher who comes in to replace another is a…","c":["Relief pitcher (reliever)","Starter","Pinch runner","Batboy"],"why":"A reliever!"},{"t":"talk","k":"more","q":"What kind of personality makes a good closer?","peek":"Calm under pressure, confident, short memory.","clue":"How do you stay calm when everyone's watching?"}]},
    {"id":"baseball-067","q":"What do the coaches standing near first and third base do?","c":["Give signals and tell runners when to run","Catch foul balls","Sell snacks","Call strikes"],"skill":"rules","why":"Base coaches give signs and wave runners home or tell them to stop!","hint":"They help the runners…","deeper":[{"t":"mc","k":"more","q":"A coach touching their cap, nose and arm in a row is probably…","c":["Giving a secret sign","Itchy","Dancing","Waving to family"],"why":"Secret signs!"},{"t":"talk","k":"more","q":"Make up a secret sign for 'steal second base'. Why must it be tricky?","peek":"Any sign; tricky so the other team can't read it.","clue":"What if the other team figured out your sign?"}]},
    {"id":"baseball-068","q":"A 'balk' is called when the pitcher…","c":["Makes an illegal move to trick a runner","Throws a strike","Catches a ball","Hits a homer"],"skill":"rules","why":"A balk is an illegal fake-out move; every runner gets to move up one base!","hint":"It's a penalty for the pitcher being too tricky…","deeper":[{"t":"mc","k":"more","q":"After a balk, runners on base…","c":["Each move up one base","Go back to home","Are out","Switch teams"],"why":"Free base!"},{"t":"talk","k":"why","q":"Why do you think tricking runners is limited by rules?","peek":"Keeps it fair; runners need to know when the pitch is coming.","clue":"What if a pitcher could fake forever?"}]},
    {"id":"baseball-069","q":"Which kind of out lets a runner on third tag up and score?","c":["A sacrifice fly","A strikeout","A pop-up to the catcher","A tag at second"],"skill":"rules","why":"A sacrifice fly! A deep fly is caught, but the runner on third tags up and runs home.","hint":"The batter 'sacrifices' and hits it far in the air…","deeper":[{"t":"mc","k":"why","q":"Why is it called a 'sacrifice'?","c":["The batter gives up an out to help a run score","They give away their bat","They leave the game","It's a dance"],"why":"The batter gives up their at-bat for the team!"},{"t":"talk","k":"why","q":"Why might a team happily trade an out for a run?","peek":"Runs win games; especially late and close.","clue":"Which matters more at the end — outs or runs?"}]},
    {"id":"baseball-070","q":"Why is the pitcher's mound raised up?","c":["To help pitchers throw downhill","To drain rain only","To hide the pitcher","For the mascot"],"skill":"rules","why":"Pitching from a little hill adds downward angle that's harder to hit!","hint":"It's a little hill — what does throwing downhill do?","deeper":[{"t":"mc","k":"more","q":"In 1969, MLB lowered the mound because…","c":["Pitchers were too dominant","It was sinking","Batters were too tall","Rain"],"why":"To help batters score more!"},{"t":"talk","k":"whatif","q":"If the mound were super tall, what would happen to the game?","peek":"Pitchers would dominate, fewer runs.","clue":"Is it easier to hit a ball coming flat or steep?"}]},
    {"id":"baseball-071","q":"A player sent in to bat for someone else is a…","c":["Pinch hitter","Pinch runner","Switch hitter","Designated runner"],"skill":"rules","why":"A pinch hitter! (A pinch runner runs for someone.)","hint":"They bat in a 'pinch' — a tough moment…","deeper":[{"t":"mc","k":"more","q":"Once replaced, can the first player come back into the game?","c":["No","Yes, anytime","Only in the 9th","Only if it rains"],"why":"No — once you're out, you're out!"},{"t":"talk","k":"whatif","q":"When would a manager use a pinch hitter?","peek":"Late, close game, need a better hitter in a key spot.","clue":"Who would you want at bat with the game on the line?"}]},
    {"id":"baseball-072","q":"In T-ball, little kids hit the ball off a…","c":["Tee","Fence","Rope","Pitching robot"],"skill":"rules","why":"A tee! No pitcher — the ball sits still on a stand.","hint":"The game's name has the answer…","deeper":[{"t":"mc","k":"why","q":"Why is T-ball great for young players?","c":["They learn to hit and run without fast pitches","It's harder","No running","No ball"],"why":"Hitting practice and fun!"},{"t":"talk","k":"more","q":"What's the hardest part of hitting a ball that someone pitches?","peek":"Timing, tracking a moving ball, speed.","clue":"What's different between a still ball and a moving one?"}]},
    {"id":"baseball-073","q":"What's the black stuff some players put under their eyes?","c":["Eye black to cut glare from the sun or lights","Face paint for fun only","Mud","Chocolate"],"skill":"rules","why":"Eye black is supposed to reduce glare so players can see fly balls better!","hint":"Think about looking up into bright sunshine…","deeper":[{"t":"mc","k":"more","q":"Outfielders also wear what to help see in the sun?","c":["Sunglasses","Snorkels","Earmuffs","Masks"],"why":"Sunglasses!"},{"t":"talk","k":"more","q":"Scientists aren't 100% sure eye black works much. How could you test it?","peek":"Compare catching with and without, fair test, many tries.","clue":"How would you make the test fair?"}]},
    {"id":"baseball-074","q":"A batter who gets hit by a pitch…","c":["Goes to first base","Is out","Gets 3 strikes","Bats again"],"skill":"rules","why":"They take first base (if they tried to avoid it).","hint":"It's like a walk…","deeper":[{"t":"mc","k":"more","q":"A ball that's thrown way past the catcher so runners can move up is a…","c":["Wild pitch","Fast pitch","Foul tip","Home run"],"why":"A wild pitch!"},{"t":"talk","k":"why","q":"Why should batters try to get out of the way of a pitch?","peek":"Safety, and the rules require trying to avoid it.","clue":"What could happen if you lean into it?"}]},
    {"id":"baseball-075","q":"Who throws to the batter?","c":["The pitcher","The catcher","The shortstop","The umpire"],"skill":"rules","why":"The pitcher! They stand on the mound in the middle of the infield.","hint":"They stand on the little hill…","deeper":[{"t":"mc","k":"more","q":"A pitcher who throws with the left hand is often called a…","c":["Lefty (southpaw)","Northpaw","Righty","Switcher"],"why":"A southpaw!"},{"t":"talk","k":"why","q":"Why might a team want both left- and right-handed pitchers?","peek":"Matchups — hitters often struggle against same-side pitchers.","clue":"Is it harder to see a ball coming from behind you?"}]},
    {"id":"baseball-076","q":"Where do the Toronto Blue Jays hold spring training?","c":["Dunedin, Florida","Iqaluit, Nunavut","Toronto","Paris"],"skill":"teams","why":"Dunedin, Florida — warm weather in February and March!","hint":"Somewhere warm in February…","deeper":[{"t":"mc","k":"why","q":"Why do teams train somewhere warm in late winter?","c":["Snowy fields can't be played on","For the beaches only","It's cheaper","No reason"],"why":"No snowy diamonds!"},{"t":"talk","k":"more","q":"What do you think players practise first in spring training?","peek":"Throwing, catching, conditioning, pitchers' arms slowly.","clue":"What gets rusty over winter?"}]},
    {"id":"baseball-077","q":"The Blue Jays' very first game, on April 7, 1977, was famous for…","c":["Being played in snow","Being on the moon","No fans","Being 30 innings"],"skill":"teams","why":"It snowed! They played anyway at Exhibition Stadium — and won 9–5.","hint":"Toronto in early April… what might fall from the sky?","deeper":[{"t":"mc","k":"more","q":"Today the Blue Jays play in a stadium with a…","c":["Roof that can open and close","Pool for fans","Ice rink","Dirt seats"],"why":"Retractable roof at the Rogers Centre!"},{"t":"talk","k":"why","q":"Why is a roof that opens and closes handy in Toronto?","peek":"Rain, cold, snow in spring/fall; sunny days open.","clue":"What's the weather like in April and October?"}]},
    {"id":"baseball-078","q":"The Toronto Blue Jays won the World Series in which two years in a row?","c":["1992 and 1993","1977 and 1978","2015 and 2016","2001 and 2002"],"skill":"teams","why":"1992 and 1993! In 1993, Joe Carter won it with a walk-off home run.","hint":"Early 1990s…","deeper":[{"t":"mc","k":"more","q":"Joe Carter's famous 1993 homer was a…","c":["Walk-off","Bunt","Grand slam in the 1st","Foul ball"],"why":"A walk-off to win the World Series!"},{"t":"talk","k":"why","q":"Why do fans still talk about that home run 30+ years later?","peek":"Rare, dramatic, won the title for Canada.","clue":"How would you feel if you saw it live?"}]},
    {"id":"baseball-079","q":"The Canadian Baseball Hall of Fame is in which Ontario town?","c":["St. Marys","Ottawa","Sudbury","Thunder Bay"],"skill":"teams","why":"St. Marys, Ontario! (The US one is in Cooperstown, New York.)","hint":"It's a small town with a saint's name.","deeper":[{"t":"mc","k":"more","q":"The National Baseball Hall of Fame in the USA is in…","c":["Cooperstown, New York","Los Angeles","Boston","Miami"],"why":"Cooperstown!"},{"t":"talk","k":"whatif","q":"If you could put one item in a Hall of Fame, what would it be and why?","peek":"Any item with a story.","clue":"What tells the best story?"}]},
    {"id":"baseball-080","q":"During World War II, a women's professional baseball league started in the USA. About how many Canadians played in it?","c":["About 60","None","Just 1","About 5,000"],"skill":"teams","why":"About 60+ Canadian women played in the All-American Girls Professional Baseball League!","hint":"More than a few dozen…","deeper":[{"t":"mc","k":"more","q":"Which movie told the story of that league?","c":["A League of Their Own","Toy Story","Frozen","The Sandlot"],"why":"A League of Their Own (1992)!"},{"t":"talk","k":"why","q":"Why might a women's league have started while many men were away at war?","peek":"Keep baseball going, entertain fans; women showed their skills.","clue":"Where were many male players during the war?"}]},
    {"id":"baseball-081","q":"The first game of the MLB season is a big celebration called…","c":["Opening Day","Closing Day","First Pitch Week","Bat Day"],"skill":"teams","why":"Opening Day! A special guest often throws the 'ceremonial first pitch'.","hint":"The season 'opens'…","deeper":[{"t":"mc","k":"more","q":"The 'ceremonial first pitch' is usually thrown by…","c":["A special guest","The umpire","The mascot only","Nobody"],"why":"A special guest!"},{"t":"talk","k":"whatif","q":"If you threw the first pitch, how would you practise beforehand?","peek":"Practise aim/distance with someone catching.","clue":"What's the scariest part?"}]},
    {"id":"baseball-082","q":"Before moving to Los Angeles in 1958, the Dodgers played in which New York borough?","c":["Brooklyn","Manhattan","Toronto","Queens Village"],"skill":"teams","why":"Brooklyn! They were the Brooklyn Dodgers when Jackie Robinson joined them.","hint":"It's a famous part of New York City that rhymes with 'look-in'.","deeper":[{"t":"mc","k":"more","q":"The name 'Dodgers' comes from people dodging…","c":["Streetcars (trolleys)","Snowballs","Baseballs","Taxes"],"why":"Trolley Dodgers!"},{"t":"talk","k":"more","q":"How do you think Brooklyn fans felt when their team moved away?","peek":"Sad, angry, betrayed.","clue":"How would you feel if your team moved?"}]},
    {"id":"baseball-083","q":"The World Series is sometimes called the…","c":["Fall Classic","Spring Fling","Winter Games","Summer Slam"],"skill":"teams","why":"The Fall Classic — it's played in October!","hint":"What season is October in?","deeper":[{"t":"mc","k":"more","q":"How many wins does a team need to win the World Series?","c":["4","1","7","10"],"why":"4 wins — best of 7!"},{"t":"talk","k":"why","q":"Why is a 'best of 7' series fairer than one game?","peek":"Luck evens out; the better team usually wins more.","clue":"Can a weaker team get lucky once?"}]},
    {"id":"baseball-084","q":"Wearing your cap inside-out to help your team come back is called a…","c":["Rally cap","Lucky lid","Hat trick","Bonnet"],"skill":"teams","why":"A rally cap! It's a fun superstition when your team is behind.","hint":"It helps your team 'rally' (come back)…","deeper":[{"t":"mc","k":"more","q":"A superstition is…","c":["A belief that something brings luck even though it doesn't cause the result","A science fact","A rule","A pitch"],"why":"A fun belief about luck!"},{"t":"talk","k":"more","q":"Do you think a rally cap really helps? How could you check?","peek":"Count wins with and without — probably no effect but fun.","clue":"Can a hat change how a ball flies?"}]},
    {"id":"baseball-085","q":"Small cards with a player's picture on the front and stats on the back are called…","c":["Baseball cards","Postcards","Library cards","Credit cards"],"skill":"teams","why":"Baseball cards! People have collected them for over 100 years.","hint":"You collect and trade them…","deeper":[{"t":"mc","k":"more","q":"A very rare old baseball card can be worth…","c":["Millions of dollars","10 cents","Nothing","A hot dog"],"why":"Some sell for millions!"},{"t":"talk","k":"more","q":"What makes a collectible card worth a lot?","peek":"Rare, famous player, great condition, old.","clue":"Why would someone pay more for something rare?"}]},
    {"id":"baseball-086","q":"The MLB All-Star Game happens in the middle of the season, in…","c":["July","January","October","April"],"skill":"teams","why":"Mid-July! The night before is the Home Run Derby.","hint":"Middle of summer…","deeper":[{"t":"mc","k":"more","q":"In the Home Run Derby, players try to…","c":["Hit as many homers as they can","Steal bases","Pitch fastest","Run a marathon"],"why":"Bombs away!"},{"t":"talk","k":"whatif","q":"If you picked the All-Star team, what would you look for?","peek":"Best stats, fan favourites, all positions.","clue":"How would you pick fairly?"}]},
    {"id":"baseball-087","q":"The Buffalo Bisons are the Blue Jays' top 'minor league' team. What is the minor leagues for?","c":["Developing players for the big leagues","Little kids only","Retired players","Umpires"],"skill":"teams","why":"Players improve in the minors and get 'called up' to the majors!","hint":"It's where players get ready for the 'major' leagues…","deeper":[{"t":"mc","k":"more","q":"Being moved up from the minors to the majors is called…","c":["Getting called up","Getting sent home","Getting traded to the moon","Retiring"],"why":"Called up!"},{"t":"talk","k":"more","q":"How do you think a player feels getting called up for the first time?","peek":"Excited, nervous, proud.","clue":"Who would they call first?"}]},
    {"id":"baseball-088","q":"Shohei Ohtani is famous because he is a star both as a…","c":["Hitter and pitcher","Goalie and coach","Umpire and mascot","Catcher and umpire"],"skill":"teams","why":"He's a 'two-way player': he pitches AND hits — very rare!","hint":"He does two jobs: throws to batters and…","deeper":[{"t":"mc","k":"more","q":"Ohtani is from which country?","c":["Japan","Brazil","Canada","Egypt"],"why":"Japan!"},{"t":"talk","k":"why","q":"Why is it so hard to be great at both pitching and hitting?","peek":"Lots of practice time for each, tired arm, different skills.","clue":"How much time do you need to get great at one thing?"}]},
    {"id":"baseball-089","q":"The scoreboard shows the Jays scored 1, 0, 2, 0, 0, 3 in the first six innings. How many runs so far?","c":["6","5","7","3"],"skill":"math","why":"1 + 0 + 2 + 0 + 0 + 3 = 6 runs!","hint":"Add only the non-zero numbers: 1, 2 and 3.","deeper":[{"t":"mc","k":"whatif","q":"If they score 2 more in the 7th, the total is…","c":["8","7","9","10"],"why":"6 + 2 = 8!"},{"t":"talk","k":"why","q":"Why are zeros helpful when adding up a scoreboard?","peek":"Adding 0 doesn't change the total, so skip them.","clue":"What's 5 + 0?"}]},
    {"id":"baseball-090","q":"A batter gets 1 hit in every 4 at-bats. What is their batting average?","c":[".250",".400",".100",".500"],"skill":"math","why":"1 out of 4 is one quarter = .250!","hint":"1 out of 4 is the same as 25 out of 100…","deeper":[{"t":"mc","k":"more","q":"Which average is better, .250 or .300?","c":[".300",".250","Same","Neither"],"why":".300 — more hits per try!"},{"t":"talk","k":"more","q":"Even great hitters fail about 7 out of 10 times. What does that teach us about trying?","peek":"Failing is normal; keep trying; success is about persistence.","clue":"Do you give up after a miss?"}]},
    {"id":"baseball-091","q":"Each team gets 3 outs per half-inning. How many outs happen in one full inning (both teams)?","c":["6","3","9","12"],"skill":"math","why":"3 + 3 = 6 outs per full inning!","hint":"Each team gets 3 outs…","deeper":[{"t":"mc","k":"more","q":"How many outs in 9 full innings, both teams?","c":["54","27","36","81"],"why":"6 × 9 = 54!"},{"t":"talk","k":"whatif","q":"When would a game have FEWER than 54 outs?","peek":"Home team ahead after top of 9th doesn't bat; walk-offs; rain.","clue":"Does the home team bat in the 9th if they're winning?"}]},
    {"id":"baseball-092","q":"A family of 4 goes to a game. Tickets are $15 each. How much in total?","c":["$60","$45","$19","$75"],"skill":"math","why":"4 × $15 = $60!","hint":"15 + 15 = 30, and 30 + 30 = …","deeper":[{"t":"mc","k":"more","q":"Hot dogs are $5 each. 4 hot dogs cost…","c":["$20","$9","$15","$25"],"why":"4 × 5 = $20!"},{"t":"talk","k":"more","q":"How could the family plan to save money at the game?","peek":"Bring snacks if allowed, budget, cheaper seats.","clue":"What costs money at a game?"}]},
    {"id":"baseball-093","q":"A pitcher threw 20 pitches. 12 were strikes. How many were balls?","c":["8","12","10","32"],"skill":"math","why":"20 − 12 = 8 balls!","hint":"Pitches = strikes + balls. Take the strikes away from 20.","deeper":[{"t":"mc","k":"more","q":"Did the pitcher throw more strikes or balls?","c":["Strikes","Balls","Same","Can't tell"],"why":"12 strikes is more than 8 balls!"},{"t":"talk","k":"why","q":"Why do coaches want pitchers to throw lots of strikes?","peek":"Fewer walks, quicker outs, fewer pitches.","clue":"What happens after 4 balls?"}]},
    {"id":"baseball-094","q":"A stadium holds 40,000 fans. 30,000 came. How many seats were empty?","c":["10,000","70,000","1,000","20,000"],"skill":"math","why":"40,000 − 30,000 = 10,000!","hint":"Think 40 − 30, then add the thousands back.","deeper":[{"t":"mc","k":"more","q":"Was the stadium more than half full?","c":["Yes","No","Exactly half","Empty"],"why":"30,000 is more than 20,000 (half)!"},{"t":"talk","k":"why","q":"Why do you think more fans come on weekends?","peek":"No school/work, family time.","clue":"When are you free to go to a game?"}]},
    {"id":"baseball-095","q":"A runner is on second base. A hit lets them run 2 more bases. Where do they end up?","c":["Home (they score!)","Third base","First base","Dugout"],"skill":"math","why":"Second → third → home. They score!","hint":"Count: from second, the next base is third, then…","deeper":[{"t":"mc","k":"more","q":"From first base, how many bases to get home?","c":["3","1","2","4"],"why":"First → second → third → home = 3!"},{"t":"talk","k":"why","q":"Why is a runner on second called 'in scoring position'?","peek":"A single can often bring them home.","clue":"How far is second from home?"}]},
    {"id":"baseball-096","q":"A game starts at 7:00 and lasts 2 hours and 40 minutes. When does it end?","c":["9:40","9:00","8:40","10:00"],"skill":"math","why":"7:00 + 2 hours = 9:00, plus 40 minutes = 9:40!","hint":"First add the hours, then the minutes.","deeper":[{"t":"mc","k":"whatif","q":"If the game went to extra innings and lasted 30 more minutes, it would end at…","c":["10:10","9:70","10:30","9:50"],"why":"9:40 + 30 min = 10:10!"},{"t":"talk","k":"why","q":"Why is 9:70 not a real time?","peek":"Only 60 minutes in an hour; it rolls over to 10:10.","clue":"How many minutes in an hour?"}]},
    {"id":"baseball-097","q":"A player got on base 6 times in 10 trips to the plate. Is that more or less than half?","c":["More than half","Less than half","Exactly half","Zero"],"skill":"math","why":"Half of 10 is 5, and 6 is more!","hint":"What's half of 10?","deeper":[{"t":"mc","k":"more","q":"6 out of 10 is the same as…","c":["60%","6%","16%","100%"],"why":"60 out of 100 = 60%!"},{"t":"talk","k":"why","q":"Why do we compare numbers 'out of 10' or 'out of 100'?","peek":"Easier to compare fairly.","clue":"Is 3 out of 5 better than 5 out of 10?"}]},
    {"id":"baseball-098","q":"A team won 5 of its first 8 games. How many did it lose?","c":["3","5","8","13"],"skill":"math","why":"8 − 5 = 3 losses (if there were no ties)!","hint":"Games = wins + losses.","deeper":[{"t":"mc","k":"whatif","q":"If they win the next 2, the record is…","c":["7 wins, 3 losses","5 wins, 5 losses","6 wins, 4 losses","7 wins, 1 loss"],"why":"7–3!"},{"t":"talk","k":"more","q":"Is a 7–3 team good? How do you decide?","peek":"Won 70%; compare to others; more than half.","clue":"Did they win more than half?"}]},
    {"id":"baseball-099","q":"A Little League field has bases 60 feet apart. How far does a batter run on a home run?","c":["240 feet","60 feet","120 feet","360 feet"],"skill":"math","why":"4 bases × 60 feet = 240 feet!","hint":"How many base paths are there around the diamond?","deeper":[{"t":"mc","k":"more","q":"In MLB, bases are 90 feet apart. A home run trot is…","c":["360 feet","180 feet","270 feet","90 feet"],"why":"4 × 90 = 360 feet!"},{"t":"talk","k":"why","q":"Why are kids' bases closer together than big-league bases?","peek":"Kids are smaller; shorter runs/throws keep it fair and fun.","clue":"Could a 7-year-old throw 90 feet?"}]},
    {"id":"baseball-100","q":"A team scored 3 runs in each of 3 innings. How many runs?","c":["9","6","12","33"],"skill":"math","why":"3 + 3 + 3 = 3 × 3 = 9!","hint":"3 groups of 3…","deeper":[{"t":"mc","k":"more","q":"And if they scored 3 runs in 4 innings?","c":["12","7","9","34"],"why":"4 × 3 = 12!"},{"t":"talk","k":"why","q":"Why is multiplying quicker than adding the same number lots of times?","peek":"Shortcut; repeated addition.","clue":"How long would adding 3 ten times take?"}]},
    {"id":"baseball-101","q":"A pack of 12 baseball cards is shared equally between 3 kids. How many does each get?","c":["4","3","6","9"],"skill":"math","why":"12 ÷ 3 = 4 cards each!","hint":"Deal them out one at a time to 3 people…","deeper":[{"t":"mc","k":"whatif","q":"If 4 kids shared the 12 cards, each would get…","c":["3","4","2","6"],"why":"12 ÷ 4 = 3!"},{"t":"talk","k":"more","q":"What's a fair way to share if one card is super rare?","peek":"Take turns picking, trade, flip a coin.","clue":"How do you make sure everyone's happy?"}]}
  ],
  holes: [
    {"id":"pitch","title":"How Pitches Curve","emoji":"⚾","match":"pitch|curve|knuckle|throw|mound|fastball|strike|ball|catcher|spin","depth":5,"size":8,"root":{"id":"baseball:pitch","k":"why","d":"Why does a curveball curve?","t":"mc","q":"A curveball curves because of its…","c":["Spin pushing air to one side","Weight","Colour","Seams being sticky"],"why":"Spin! The ball pushes air one way, and the air pushes it the other.","next":[{"id":"baseball:pitch.0","k":"more","d":"Why the seams matter","t":"mc","q":"The raised red seams help pitchers by…","c":["Grabbing the air to make more spin effects","Making it heavier","Looking nice only","Making noise"],"why":"The seams 'grab' air!","next":[{"id":"baseball:pitch.0.0","k":"whatif","d":"What if no spin?","t":"mc","q":"What if a ball has almost no spin, like a knuckleball?","c":["It wobbles unpredictably","It goes straight forever","It floats up","It stops"],"why":"Wobble, flutter, dance!","next":[{"id":"baseball:pitch.0.0.0","k":"why","d":"Why so hard to hit?","t":"talk","q":"Why do you think hitters find a fluttering pitch so hard to hit?","peek":"They can't predict where it'll be when it reaches the plate.","clue":"Can you catch a leaf falling in the wind?","next":[{"id":"baseball:pitch.0.0.0.0","k":"more","d":"Catching the uncatchable","t":"mc","q":"Catchers for knuckleball pitchers often use a…","c":["Bigger-than-normal catcher's mitt","Hockey goalie glove","Butterfly net","Bucket"],"why":"An extra-big mitt helps snag the dancing ball!","next":[]}]}]}]},{"id":"baseball:pitch.1","k":"more","d":"How fast is a fastball?","t":"mc","q":"Big-league fastballs often go about…","c":["150 km/h","20 km/h","500 km/h","1 km/h"],"why":"Around 150 km/h — and some over 160!","next":[{"id":"baseball:pitch.1.0","k":"whatif","d":"Reaction time","t":"talk","q":"A 150 km/h pitch reaches the plate in less than half a second. What if you had to decide to swing in a blink?","peek":"Hitters must guess early using clues like the pitcher's arm and grip.","clue":"How long is a blink?","next":[{"id":"baseball:pitch.1.0.0","k":"more","d":"Try it!","t":"talk","q":"Try a reaction game: a grown-up drops a ruler and you catch it. How far did it fall? What helps you react faster?","peek":"Being ready, focusing, practice.","clue":"Did you get faster with practice?","next":[]}]}]}]}},
    {"id":"bat","title":"Bats, Balls & Physics","emoji":"🏏","match":"bat|home run|hit|swing|homer|wood|maple|batter|bunt|hard","depth":5,"size":7,"root":{"id":"baseball:bat","k":"more","d":"The sweet spot","t":"mc","q":"The 'sweet spot' on a bat is…","c":["The spot where hits feel best and fly farthest","The handle","Where you put sugar","The knob"],"why":"Hit it there and the bat barely stings!","next":[{"id":"baseball:bat.0","k":"why","d":"Why does it sting?","t":"talk","q":"Hitting the ball near the handle can sting your hands. Why might that happen?","peek":"The bat vibrates; away from the sweet spot more shaking goes into your hands.","clue":"What does a bat do when it's hit — sit still or shake?","next":[{"id":"baseball:bat.0.0","k":"whatif","d":"What if the bat breaks?","t":"mc","q":"Wooden bats sometimes break. Why do many players use maple?","c":["It's very hard and strong","It's soft","It's lighter than air","It smells like syrup"],"why":"Hard maple drives the ball!","next":[{"id":"baseball:bat.0.0.0","k":"more","d":"Ball distance","t":"talk","q":"Home runs fly farther in Denver, a mile above sea level. Why might the ball go farther there?","peek":"Thinner air means less air resistance.","clue":"Is it easier to run through thick or thin air?","next":[{"id":"baseball:bat.0.0.0.0","k":"whatif","d":"Baseball on the Moon?","t":"talk","q":"What if you pitched a curveball on the Moon, where there's no air at all? Would it still curve?","peek":"No — spin needs air to push against, so it would fly straight (and super far in low gravity!).","clue":"What does the spinning ball push against on Earth?","next":[]}]}]}]},{"id":"baseball:bat.1","k":"whatif","d":"What's inside a baseball?","t":"mc","q":"Under the leather, a baseball is tightly wrapped with…","c":["Long yarn","Paper","Feathers","Spaghetti"],"why":"Hundreds of metres of yarn around a cork-and-rubber centre!","next":[{"id":"baseball:bat.1.0","k":"why","d":"Why so tightly wound?","t":"talk","q":"Why do you think the yarn is wrapped so tightly?","peek":"Makes the ball hard and bouncy, flies far, keeps its shape.","clue":"What would a loose ball do when hit?","next":[]}]}]}},
    {"id":"bbhistory","title":"Baseball Heroes & History","emoji":"🧢","match":"jackie|robinson|history|hall of fame|expos|blue jays|babe ruth|aaron|league|1947|montreal|world series|canad|park|stadium|field|wall|fans|cap|coach|dugout|shortstop|position|plate|game","depth":4,"size":6,"root":{"id":"baseball:bbhistory","k":"more","d":"Jackie Robinson in Montreal","t":"mc","q":"Montreal fans in 1946 treated Jackie Robinson…","c":["With warm cheers and support","Badly","They ignored him","They never saw him"],"why":"Montreal fans cheered him — he remembered it all his life.","next":[{"id":"baseball:bbhistory.0","k":"why","d":"Why was he so brave?","t":"talk","q":"Jackie Robinson promised not to fight back against cruelty for his first years. Why was that so hard — and so powerful?","peek":"He had to stay calm while treated unfairly; showed strength and changed minds.","clue":"Is it harder to fight back or to stay calm?","next":[{"id":"baseball:bbhistory.0.0","k":"more","d":"Number 42","t":"mc","q":"Every MLB player wears number 42 on April 15 to honour…","c":["Jackie Robinson","Babe Ruth","The 42nd president","Ace the mascot"],"why":"Jackie Robinson Day!","next":[{"id":"baseball:bbhistory.0.0.0","k":"whatif","d":"What if you could honour someone?","t":"talk","q":"If everyone wore one number to honour a hero of yours, whose number would it be and why?","peek":"Any hero with a reason.","clue":"Who inspires you?","next":[]}]}]},{"id":"baseball:bbhistory.1","k":"more","d":"Canada's teams","t":"mc","q":"The Montreal Expos played in MLB from 1969 until…","c":["2004 (they became the Washington Nationals)","1970","Today","1867"],"why":"They moved to Washington in 2005 and became the Nationals.","next":[{"id":"baseball:bbhistory.1.0","k":"why","d":"Why do teams move?","t":"talk","q":"Why might a baseball team move to a new city?","peek":"Money, fans, stadium problems.","clue":"What does a team need to survive?","next":[]}]}]}},
    {"id":"stats","title":"Baseball by the Numbers","emoji":"📊","match":"average|math|stat|runs|innings|outs|percent|score|count|rbi|era","depth":4,"size":6,"root":{"id":"baseball:stats","k":"more","d":"What's a batting average?","t":"mc","q":"A batting average is hits divided by…","c":["At-bats","Home runs","Innings","Fans"],"why":"Hits ÷ at-bats!","next":[{"id":"baseball:stats.0","k":"why","d":"Why 3 decimal places?","t":"talk","q":"Batting averages look like .287. Why do you think they use 3 decimal places?","peek":"To tell close players apart.","clue":"Are .287 and .290 different?","next":[{"id":"baseball:stats.0.0","k":"whatif","d":"What if you hit .400?","t":"mc","q":"Nobody has hit .400 in a full MLB season since 1941. What does .400 mean?","c":["4 hits every 10 at-bats","40 home runs","400 runs","4 strikeouts"],"why":"4 out of 10 — super rare!","next":[{"id":"baseball:stats.0.0.0","k":"more","d":"Moneyball thinking","t":"talk","q":"Some teams use numbers to find underrated players. What numbers would you track for your favourite player?","peek":"Hits, walks, runs, strikeouts — any thoughtful choice.","clue":"What helps a team win?","next":[]}]}]},{"id":"baseball:stats.1","k":"whatif","d":"Lower is better?","t":"mc","q":"For a pitcher's ERA (earned run average), a good number is…","c":["Lower","Higher","Exactly 100","Negative"],"why":"Lower — fewer runs allowed!","next":[{"id":"baseball:stats.1.0","k":"why","d":"Why are some stats backwards?","t":"talk","q":"Why is a LOW number good for pitchers but a HIGH number good for hitters?","peek":"Pitchers want to stop runs; hitters want to make them.","clue":"What does each player want to happen?","next":[]}]}]}}
  ]
};
